<?php
declare(strict_types=1);
require_once __DIR__ . '/config/role_security_alerts.php';

$error=null;$success=null;$accounts=[];$alerts=[];$csrf='';$openCount=0;
try{
    $pdo=role_portal_db();role_security_ensure($pdo);security_step17_session_start();
    $actor=security_step17_session_user($pdo,true);
    if(!$actor){header('Location: ../login.php');exit;}
    if((int)($actor['must_change_password']??0)===1){header('Location: ../change_password.php?required=1');exit;}
    if((string)($actor['role_code']??'')!=='admin'){header('Location: ../'.role_portal_home($actor));exit;}
    if(!security_step17_has_permission($pdo,'security.users.manage',$actor)){header('Location: access_denied.php?permission=security.users.manage');exit;}
    $ctx=security_step17_context($pdo);$orgId=(int)$ctx['organization_id'];$csrf=security_step17_csrf();

    if($_SERVER['REQUEST_METHOD']==='POST'){
        security_step17_verify_csrf((string)($_POST['csrf']??''));
        $action=(string)($_POST['action']??'');
        if($action==='lock'){
            role_security_set_lock($pdo,(int)($_POST['user_id']??0),true,(string)($_POST['reason']??''));
            $success='Account locked and its active sessions were revoked.';
        }elseif($action==='unlock'){
            role_security_set_lock($pdo,(int)($_POST['user_id']??0),false);
            $success='Account unlocked. The user must sign in again with valid credentials.';
        }elseif($action==='resolve_alert'){
            role_security_admin_resolve_alert($pdo,(int)($_POST['alert_id']??0));
            $success='Security alert resolved and retained in audit history.';
        }
    }

    $accounts=role_security_account_rows($pdo,$orgId);$alerts=role_security_admin_alerts($pdo,$orgId,180);$openCount=role_security_open_alert_count($pdo,$orgId,null);
}catch(Throwable $e){$error=$e->getMessage();}
function asa_when(?string $v):string{if(!$v)return '—';$t=strtotime($v);return $t?date('d M Y, h:i A',$t):$v;}
function asa_label(string $v):string{return strtoupper(str_replace('_',' ',$v));}
?><!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Account Security - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><link rel="stylesheet" href="assets/step10.css"><style>
.security-account-grid{display:grid;gap:10px}.security-account{padding:14px;border:1px solid #dfe8e3;border-radius:15px;background:#fff}.security-account.locked{background:linear-gradient(145deg,#fff,#fff0f0);border-color:#edcfd2}.security-account-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.security-account h3{margin:0;font-size:.92rem}.security-account p{margin:5px 0 0;color:#6d7d75;font-size:.72rem}.security-account-actions{display:grid;grid-template-columns:minmax(220px,1fr) auto;gap:8px;margin-top:11px;align-items:end}.security-account-actions input{width:100%;padding:10px;border:1px solid #d5e1da;border-radius:10px}.alert-list{display:grid;gap:9px}.admin-alert{padding:13px;border:1px solid #dfe8e3;border-radius:14px;background:#fff}.admin-alert.high,.admin-alert.critical{background:#fff2f2;border-color:#eccfd2}.admin-alert.medium{background:#fff9e8}.admin-alert-head{display:flex;justify-content:space-between;gap:12px}.admin-alert h3{margin:0;font-size:.86rem}.admin-alert p{margin:5px 0 0;color:#697a71;font-size:.71rem;line-height:1.5}.admin-alert-meta{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}.security-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}.security-kpis>div{padding:12px;border:1px solid #dfe8e3;border-radius:13px;background:rgba(255,255,255,.78)}.security-kpis span{display:block;color:#74837b;font-size:.66rem}.security-kpis b{display:block;margin-top:4px;font-size:1rem}@media(max-width:820px){.security-account-actions{grid-template-columns:1fr}.security-kpis{grid-template-columns:1fr}.security-account-head,.admin-alert-head{flex-direction:column}}
</style></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="role_accounts.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>Advanced Login • Account Security</small></span></a><div class="os-top-actions"><a class="os-btn" href="role_accounts.php">Role Accounts</a><a class="os-btn" href="security_sessions.php">Sessions</a><a class="os-btn primary" href="security_center.php">Security</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Account Security</div><nav class="os-nav"><a class="active" href="account_security.php"><i class="dot"></i>Locks & Alerts</a><a href="role_accounts.php"><i class="dot"></i>Role Accounts</a><a href="password_recovery.php"><i class="dot"></i>Password Recovery</a><a href="security_sessions.php"><i class="dot"></i>Sessions</a><a href="security_audit.php"><i class="dot"></i>Audit</a></nav><div class="os-sidebar-status"><b>Safe response model</b><span>Risk detection creates alerts first. Administrator lock is explicit and immediately revokes the target account's active sessions.</span></div></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">LOCK • ALERT • REVIEW</div><h1>Control account access and review suspicious sign-in patterns.</h1><p>New browser/IP and repeated failed-attempt patterns create security alerts. They do not automatically lock a legitimate user. Administrator decides when a lock is necessary.</p><div class="security-kpis"><div><span>Open alerts</span><b><?=$openCount?></b></div><div><span>Accounts</span><b><?=count($accounts)?></b></div><div><span>Locked accounts</span><b><?=count(array_filter($accounts,static fn($a)=>(int)$a['is_locked']===1))?></b></div></div></section><?php if($error):?><div class="pp-alert bad"><strong>Account security:</strong> <?=security_step17_h($error)?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Done:</strong> <?=security_step17_h($success)?></div><?php endif;?><section class="pp-grid"><article class="os-card pp-span-6"><h2>Account Lock / Unlock Status</h2><p>Locking an account signs it out everywhere. Your currently signed-in Administrator account cannot be locked here.</p><div class="security-account-grid" style="margin-top:13px"><?php foreach($accounts as $a):$locked=(int)$a['is_locked']===1;?><div class="security-account <?=$locked?'locked':''?>"><div class="security-account-head"><div><h3><?=security_step17_h((string)$a['full_name'])?></h3><p><?=security_step17_h((string)$a['email'])?> • <?=security_step17_h(strtoupper((string)$a['role_code']))?> • Last login <?=security_step17_h(asa_when((string)($a['last_login_at']??'')))?></p></div><span class="pp-badge <?=$locked?'warn':''?>"><?=$locked?'LOCKED':'ACTIVE'?></span></div><div class="admin-alert-meta"><span class="pp-badge"><?=(int)$a['open_alerts']?> open alert(s)</span><?php if((int)$a['high_alerts']>0):?><span class="pp-badge warn"><?=(int)$a['high_alerts']?> high</span><?php endif;?><?php if($locked&&$a['lock_reason']):?><span class="pp-badge warn"><?=security_step17_h((string)$a['lock_reason'])?></span><?php endif;?></div><?php if((int)$a['id']!==(int)($actor['id']??0)):?><?php if($locked):?><form method="post" style="margin-top:11px"><input type="hidden" name="csrf" value="<?=security_step17_h($csrf)?>"><input type="hidden" name="action" value="unlock"><input type="hidden" name="user_id" value="<?=(int)$a['id']?>"><button class="os-btn" type="submit">Unlock Account</button></form><?php else:?><form method="post" class="security-account-actions" onsubmit="return confirm('Lock this account and sign it out on every active device?')"><input type="hidden" name="csrf" value="<?=security_step17_h($csrf)?>"><input type="hidden" name="action" value="lock"><input type="hidden" name="user_id" value="<?=(int)$a['id']?>"><label>Security reason<input name="reason" required minlength="5" maxlength="255" placeholder="Example: suspicious sign-in under review"></label><button type="submit">Lock & Revoke Sessions</button></form><?php endif;?><?php else:?><p style="margin-top:10px"><strong>Current Administrator:</strong> self-lock is disabled to prevent accidental administrative lockout.</p><?php endif;?></div><?php endforeach;?></div></article><article class="os-card pp-span-6"><h2>Security Alert Queue</h2><p>Resolve alerts after you have reviewed the account/device activity.</p><div class="alert-list" style="margin-top:13px"><?php foreach($alerts as $a):?><div class="admin-alert <?=security_step17_h((string)$a['severity'])?>"><div class="admin-alert-head"><div><h3><?=security_step17_h((string)$a['title'])?></h3><p><strong><?=security_step17_h((string)$a['full_name'])?></strong> • <?=security_step17_h((string)$a['email'])?> • <?=security_step17_h(strtoupper((string)($a['role_code']??'')))?></p><p><?=security_step17_h((string)($a['details']?:'No additional details.'))?></p></div><span class="pp-badge <?=in_array((string)$a['severity'],['high','critical'],true)?'warn':''?>"><?=security_step17_h(strtoupper((string)$a['severity']))?></span></div><div class="admin-alert-meta"><span class="pp-badge"><?=security_step17_h(asa_label((string)$a['status']))?></span><span class="pp-badge"><?=security_step17_h(asa_when((string)$a['created_at']))?></span><?php if($a['ip_address']):?><span class="pp-badge">IP <?=security_step17_h((string)$a['ip_address'])?></span><?php endif;?></div><?php if((string)$a['status']!=='resolved'):?><form method="post" style="margin-top:10px"><input type="hidden" name="csrf" value="<?=security_step17_h($csrf)?>"><input type="hidden" name="action" value="resolve_alert"><input type="hidden" name="alert_id" value="<?=(int)$a['id']?>"><button class="os-btn" type="submit">Resolve Alert</button></form><?php endif;?></div><?php endforeach;?><?php if(!$alerts):?><div class="pp-alert">No security alerts have been recorded yet.</div><?php endif;?></div></article></section><div class="os-footer-note"><strong>Detection scope:</strong> this first release detects new browser/device signatures, new network addresses, repeated failed attempts before a successful sign-in, and simultaneous active networks. It does not guess physical location from IP.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
